import React from "react";
import { useEffect } from "react";
import { useParams } from "react-router-dom";
import { axiosInstance } from "src/network/adapter";
import { ApiEndpoints } from "src/network/endpoints";
import CurrentOpenings from "src/views/pages/Career/CurrentOpenings";
import ApplicationForm from "src/views/pages/CareerDetails/ApplicationForm";
import SeniorCopywriter from "src/views/pages/CareerDetails/SeniorCopywriter";
import { toastError, toastSuccess } from "src/utils/utils";
import { useState } from "react";
import FallbackSpinner from "src/@core/components/spinner";
import bgImg from "../../assets/images/section1BgImg.png";
import bgImgSmall from "../../assets/images/bannerSectionBgImgSmall.png";
import "../../styles/animation.css";
import { Box } from "@mui/material";

const CareerDetailsPage = () => {
  useEffect(() => {
    window.scrollTo(0, 0); // Scroll to the top when the component mounts
  }, []);
  const { id } = useParams();
  const [careerDetails, setCareerDetails] = useState([]);
  const [loading, setLoading] = useState(false);
  const [backgroundPositionY, setBackgroundPositionY] = useState(0);
  //animation
  useEffect(() => {
    const handleScroll = () => {
      const offset = window.pageYOffset || document.documentElement.scrollTop;
      setBackgroundPositionY(offset); // Set the background position directly based on scroll offset
    };

    window.addEventListener("scroll", handleScroll);
    handleScroll(); // Initialize position

    return () => {
      window.removeEventListener("scroll", handleScroll);
    };
  }, []);

  const fetchCareerData = () => {
    setLoading(true);
    axiosInstance
      .get(ApiEndpoints.CAREER_DETAILS.list(id))
      .then((response) => {
        const responseData = response.data.data;
        // if (responseData.length > 0) {
        //   setCareerDetails(responseData); // Set the first object directly
        // }
        setCareerDetails(responseData);

        // setCareerDetailsData();
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };
  useEffect(() => {
    fetchCareerData();
  }, [id]);

  if (loading) return <FallbackSpinner />;
  return (
    <>
      <Box
        sx={{
          position: "relative",
          minHeight: "100vh",
          overflowX: "hidden",
          overflowY: "auto",
          scrollBehavior: "smooth",
          transition: "2s ease-in-out",
        }}
      >
        <Box
          sx={{
            backgroundImage: { xs: `url(${bgImgSmall})`, sm: `url(${bgImg})` },
            backgroundRepeat: "no-repeat",
            backgroundPosition: `right ${backgroundPositionY}px`,
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            zIndex: -1,
            pointerEvents: "none",
            transition: "background-position 1.5s ease-in-out",
          }}
        />
        <SeniorCopywriter careerDetails={careerDetails} />
        <ApplicationForm careerDetails={careerDetails} />
        <CurrentOpenings title={"Other Openings"} />
      </Box>
    </>
  );
};

export default CareerDetailsPage;
