import {
  Box,
  Button,
  Container,
  FormControl,
  FormHelperText,
  Grid,
  MenuItem,
  TextField,
  Typography,
} from "@mui/material";
import React, { useEffect } from "react";
import { yupResolver } from "@hookform/resolvers/yup";
import * as yup from "yup";
import { Controller, useForm } from "react-hook-form";
import UploadFileIcon from "@mui/icons-material/UploadFile";
import { useState } from "react";
import Select from "react-select";
import { toastError, toastSuccess } from "src/utils/utils";
import { axiosInstance } from "src/network/adapter";
import { ApiEndpoints } from "src/network/endpoints";

const SUPPORTED_FORMATS = [
  "resume/jpg",
  "resume/jpeg",
  "resume/png",
  "resume/pdf",
];
const validationSchema = yup.object().shape({
  full_name: yup.string().trim().required("Full Name is required"),
  email: yup
    .string()
    .trim()
    .email("Invalid Email")
    .required("Email Address is required"),
  resume: yup
    .mixed()
    .required("Resume is required")
    .test(
      "fileFormat",
      "Unsupported Format. Only jpg, png, jpeg, and pdf are allowed.",
      (value) => !value || SUPPORTED_FORMATS.includes(value?.type)
    ),
});

const FileInput = ({ inputId, accept, onChange, selectedFileName, error }) => (
  <>
    <Button
      startIcon={<UploadFileIcon />}
      variant="contained"
      sx={{
        py: 7,
        boxShadow: "none",
        borderRadius: "17px",
        bgcolor: "#fff",
        borderWidth: "2px", // Increase border width
        borderStyle: "dashed", // Dashed border
        borderColor: "#C8C8C8",
        color: "#989898",
        fontSize: { sm: "16px" },
        "&:hover": {
          bgcolor: "transparent", // transparent white color on hover
          boxShadow: "none",
        },
      }}
      onClick={() => document.getElementById(inputId).click()}
    >
      Upload your Resume or CV
    </Button>
    <input
      id={inputId}
      name={inputId}
      type="file"
      accept={accept}
      onChange={onChange}
      style={{ display: "none" }}
    />
    <FormHelperText
      variant="body2"
      sx={{ color: "#6B6B6B", marginBottom: "8px" }}
    >
      {selectedFileName || "No file chosen"}
    </FormHelperText>
    <FormHelperText
      variant="body2"
      sx={{ color: "#ff0000", marginBottom: "8px" }}
    >
      {error && error.message}
    </FormHelperText>
  </>
);

const ApplicationForm = ({ careerDetails }) => {
  const {
    control,
    handleSubmit,
    reset,
    formState: { errors },
  } = useForm({
    defaultValues: {
      full_name: "",
      email: "",
      select_position: "",
      resume: "",
    },
    resolver: yupResolver(validationSchema),
    mode: "onChange",
  });
  const [selectedFileNames, setSelectedFileNames] = useState({
    resume: "",
  });

  const [careerDetailsData, setCareerDetailsData] = useState([]);
  useEffect(() => {
    setCareerDetailsData(careerDetails);
  }, [careerDetails]);

  useEffect(() => {
    if (careerDetailsData?.position) {
      reset({
        full_name: "",
        email: "",
        select_position: careerDetailsData.position,
        resume: "",
      });
    }
  }, [careerDetailsData, reset]);
  const handleFileChange = (inputName, e) => {
    const selectedFile = e.target.files[0];
    if (selectedFile) {
      setSelectedFileNames({
        ...selectedFileNames,
        resume: selectedFile.name,
      });
    }
  };

  const onSubmit = (data) => {
    let payload = {
      full_name: data.full_name,
      email: data.email,
      select_position: data.select_position,
      resume: selectedFileNames.resume,
    };

    let apiInstance = null;
    apiInstance = axiosInstance.post(
      ApiEndpoints.APPLICATION_FORM.create,
      payload
    );
    apiInstance
      .then((response) => response.data)
      .then((response) => {
        toastSuccess(response.message);
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        reset();
        setSelectedFileNames({
          resume: "",
        });
      });
  };

  return (
    <>
      <Box>
        <Container
          maxWidth={"xl"}
          sx={{
            px: { xs: 5, lg: 15, xl: 20 },
            py: { xs: 12, lg: 10, xl: 15 },
          }}
        >
          <Grid container rowGap={6}>
            <Grid item xs={12}>
              <Typography
                sx={{
                  color: "#000000",
                  fontSize: "32px",
                  lineHeight: "38px",
                  fontWeight: 500,
                }}
              >
                Application Form
              </Typography>
            </Grid>
            <Grid item xs={12}>
              <form onSubmit={handleSubmit(onSubmit)}>
                <Grid container spacing={6}>
                  <Grid item container spacing={4}>
                    {" "}
                    <Grid item xs={6}>
                      <FormControl fullWidth>
                        <Controller
                          name="full_name"
                          control={control}
                          render={({ field }) => (
                            <TextField
                              error={Boolean(errors.full_name)}
                              {...field}
                              placeholder="Full Name *"
                              fullWidth
                              sx={{
                                "& fieldset": { border: "none" },
                                "&::placeholder": {
                                  color: "#989898",
                                  fontWeight: 500,
                                },
                              }}
                              inputProps={{
                                style: {
                                  border: "1.5px solid #C8C8C8",
                                  borderRadius: "14px",
                                },
                              }}
                            />
                          )}
                        />
                        {errors.full_name && (
                          <FormHelperText sx={{ color: "#ff0000" }}>
                            {errors.full_name.message}
                          </FormHelperText>
                        )}
                      </FormControl>
                    </Grid>
                    <Grid item xs={6}>
                      {" "}
                      <FormControl fullWidth>
                        <Controller
                          name="email"
                          control={control}
                          render={({ field }) => (
                            <TextField
                              error={Boolean(errors.email)}
                              {...field}
                              placeholder="Email Address *"
                              fullWidth
                              sx={{
                                "& fieldset": { border: "none" },
                                "&::placeholder": {
                                  color: "#989898",
                                  fontWeight: 500,
                                },
                              }}
                              inputProps={{
                                style: {
                                  border: "1.5px solid #C8C8C8",
                                  borderRadius: "14px",
                                },
                              }}
                            />
                          )}
                        />
                        {errors.email && (
                          <FormHelperText sx={{ color: "#ff0000" }}>
                            {errors.email.message}
                          </FormHelperText>
                        )}
                      </FormControl>
                    </Grid>
                  </Grid>

                  <Grid item xs={12}>
                    <FormControl fullWidth>
                      <Controller
                        name="select_position"
                        control={control}
                        render={({ field }) => (
                          <TextField
                            {...field}
                            fullWidth
                            value={careerDetailsData.position}
                            sx={{
                              "& fieldset": { border: "none" },
                              "&::placeholder": {
                                color: "#989898",
                                fontWeight: 500,
                              },
                            }}
                            inputProps={{
                              readOnly: true,
                              style: {
                                border: "1.5px solid #C8C8C8",
                                borderRadius: "14px",
                              },
                            }}
                          />
                        )}
                      />
                    </FormControl>
                  </Grid>
                  <Grid item xs={12}>
                    <FormControl fullWidth>
                      <Controller
                        name="resume"
                        control={control}
                        render={({ field }) => (
                          <FileInput
                            {...field}
                            inputId="resume"
                            accept=".jpg, .jpeg, .png, .pdf"
                            onChange={(e) => handleFileChange("resume", e)}
                            selectedFileName={selectedFileNames.resume}
                            error={errors.resume}
                          />
                        )}
                      />
                    </FormControl>
                  </Grid>
                  <Grid item>
                    <Button
                      type="submit"
                      variant="contained"
                      sx={{ p: "3px 20px", borderRadius: "16px" }}
                    >
                      SUBMIT
                    </Button>
                  </Grid>
                </Grid>
              </form>
            </Grid>
          </Grid>
        </Container>
      </Box>
    </>
  );
};

export default ApplicationForm;
